export function slugify(text) {
  return String(text).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { slugify } from "../src/slugify.mjs";

test("slugify: пример из требования", () => assert.equal(slugify(" Hello, World! "), "hello-world"));
test("slugify: серия разделителей схлопывается в один дефис", () => assert.equal(slugify("a  --  b...c"), "a-b-c"));
test("slugify: цифры сохраняются", () => assert.equal(slugify("Version 2 of 10"), "version-2-of-10"));
test("slugify: пустой результат", () => {
  assert.equal(slugify(""), "");
  assert.equal(slugify(" !!! "), "");
});

